-- The Bank app on pf-devices (tablet and computer): personal, shared and society accounts, ledger
-- statements, transfers, loans, credit and cards.
--
-- Every handler runs with the player's real id after pf-devices' access check, and re-checks what it
-- touches: account membership and permissions (server_accounts.lua), society access (server.lua,
-- canUseAccount), amounts and limits. Money moves through the same functions the bank screen uses,
-- each through the ledger; the app adds a stable key per action ('bankapp:<cid>:<i|x>:<ref>', `ref`
-- generated by the app once per action), so a retried request never moves money twice.
-- Cash stays physical: the app can show the cash ledger lines but never withdraws or deposits cash.

PFBankApp = PFBankApp or {}
local App = PFBankApp
local L = PFLedger
local QBCore = exports['pfm-core']:GetCoreObject({ 'Functions', 'Shared' })

local APP_ID = 'bank'

local function cfg(key, default)
    local c = Config.App or {}
    if c[key] == nil then return default end
    return c[key]
end

local function getPlayer(src)
    local Player = exports['pfm-core']:GetPlayer(src)
    if not Player then return nil end
    return Player, Player.PlayerData.citizenid
end

local function perm(p, key) return BankingAccountsInternal.perm(p, key) == true end

-- Runs one of the bank screen's callbacks (BankingCallbacks) and returns what it answered.
local function run(name, src, data)
    local fn = BankingCallbacks and BankingCallbacks['qb-banking:server:' .. name]
    if not fn then return nil end
    local out
    fn(src, function(res) out = res end, data)
    return out
end

-- A callback answer { success, message } as an app result.
local function fromCallback(res)
    if type(res) ~= 'table' then return { ok = false, error = 'server_error' } end
    if res.success then return { ok = true, message = res.message, txId = res.txId, duplicate = res.duplicate } end
    return { ok = false, error = res.error or 'refused', message = res.message }
end

--- The action id the app sends with every money action (letters, digits and dashes, 8-40 long).
local function requestRef(payload)
    local r = payload.ref
    if type(r) ~= 'string' or #r < 8 or #r > 40 or not r:match('^[%w%-]+$') then return nil end
    return r
end

local function positiveInt(v, max)
    v = tonumber(v)
    if not v or v ~= v or v < 1 or v % 1 ~= 0 or v > (max or 1e12) then return nil end
    return v
end

-- one money action per player per Config.App.cooldownMs
local lastAction = {}
local function onCooldown(cid)
    local now = GetGameTimer()
    local last = lastAction[cid]
    if last and now - last < cfg('cooldownMs', 1500) then return true end
    lastAction[cid] = now
    return false
end

-- ── labels ──────────────────────────────────────────────────────────

local SYSTEM_LABELS = {
    paycheck = 'Paycheck', bank_fees = 'Bank fees', loans = 'Loan department', credit = 'Credit card',
    closed_accounts = 'Closed accounts', ['pfm-crypto'] = 'Qbit exchange', ['pf-devices'] = 'App Store',
    ['pf-government'] = 'City of Los Santos', ['pf-citizen'] = 'City bills', ['pfm-phone'] = 'Invoices',
}

local function societyLabel(name, accountType)
    local Shared = QBCore.Shared or {}
    local def = (accountType ~= 'gang' and Shared.Jobs and Shared.Jobs[name]) or (Shared.Gangs and Shared.Gangs[name])
    return def and def.label or name
end

local function systemLabel(name)
    if SYSTEM_LABELS[name] then return SYSTEM_LABELS[name] end
    local base = name:match('^([^:]+)') or name
    if SYSTEM_LABELS[base] then return SYSTEM_LABELS[base] end
    base = base:gsub('^pfm?%-', ''):gsub('[_%-]', ' ')
    return (base:gsub('^%l', string.upper))
end

local function charName(charinfo)
    local ok, ci = pcall(json.decode, charinfo or '')
    if not ok or type(ci) ~= 'table' then return nil end
    local name = (tostring(ci.firstname or '') .. ' ' .. tostring(ci.lastname or '')):gsub('^%s+', ''):gsub('%s+$', '')
    return name ~= '' and name or nil
end

local function placeholders(n)
    local t = {}
    for i = 1, n do t[i] = '?' end
    return table.concat(t, ', ')
end

-- Readable labels for the other side of statement lines, resolved in two batched queries.
local function describeAll(refs, cid)
    local players, accts, out = {}, {}, {}
    for ref in pairs(refs) do
        local parsed = L.ParseRef(ref)
        if parsed and parsed.kind == 'player' and parsed.citizenid ~= cid then players[parsed.citizenid] = true
        elseif parsed and parsed.kind == 'acct' then accts[parsed.id] = true end
    end
    local names, labels = {}, {}
    local pList = {}
    for id in pairs(players) do pList[#pList + 1] = id end
    if #pList > 0 then
        for _, r in ipairs(MySQL.query.await(('SELECT citizenid, charinfo FROM players WHERE citizenid IN (%s)'):format(placeholders(#pList)), pList) or {}) do
            names[r.citizenid] = charName(r.charinfo)
        end
    end
    local aList = {}
    for id in pairs(accts) do aList[#aList + 1] = id end
    if #aList > 0 then
        for _, r in ipairs(MySQL.query.await(('SELECT id, label, iban FROM bank_accounts_v2 WHERE id IN (%s)'):format(placeholders(#aList)), aList) or {}) do
            labels[tonumber(r.id)] = { label = r.label, iban = r.iban }
        end
    end
    for ref in pairs(refs) do
        local parsed = L.ParseRef(ref)
        local d = { kind = parsed and parsed.kind or 'unknown', label = 'Unknown' }
        if parsed and parsed.kind == 'player' then
            if parsed.citizenid == cid then
                d.label, d.own = (parsed.moneytype == 'cash') and 'Your cash' or 'Your personal account', true
            else
                d.label = names[parsed.citizenid] or 'A citizen'
            end
        elseif parsed and parsed.kind == 'acct' then
            local a = labels[parsed.id]
            d.label = a and a.label or 'Closed account'
            d.iban = a and a.iban or nil
        elseif parsed and parsed.kind == 'society' then
            local acc = BankingInternal.Accounts[parsed.name]
            d.label = societyLabel(parsed.name, acc and acc.account_type)
        elseif parsed and parsed.kind == 'system' then
            d.label = systemLabel(parsed.name)
        end
        out[ref] = d
    end
    return out
end

-- ── accounts the player may use ─────────────────────────────────────

--- The society accounts the player may use: their job and gang account as boss, and legacy shared
--- accounts they are listed on (canUseAccount decides, as for the bank screen).
function App.Societies(Player)
    local pd = Player.PlayerData
    local I = BankingInternal
    local out, seen = {}, {}
    local function add(name, kind)
        if seen[name] or type(name) ~= 'string' then return end
        local acc = I.Accounts[name]
        if not acc and kind ~= 'shared' then
            L.EnsureSociety(name, kind)
            acc = I.Accounts[name]
        end
        if acc and I.canUseAccount(Player, acc) then
            seen[name] = true
            out[#out + 1] = {
                ref = 'society:' .. name, name = name, type = acc.account_type,
                label = societyLabel(name, acc.account_type), balance = tonumber(acc.account_balance) or 0,
            }
        end
    end
    if pd.job and pd.job.isboss and pd.job.name and pd.job.name ~= 'unemployed' then add(pd.job.name, 'job') end
    if pd.gang and pd.gang.isboss and pd.gang.name and pd.gang.name ~= 'none' then add(pd.gang.name, 'gang') end
    for name, acc in pairs(I.Accounts) do
        if acc.account_type == 'shared' then add(name, 'shared') end
    end
    table.sort(out, function(a, b) return a.label < b.label end)
    return out
end

--- Resolves an account the app names ('personal', 'cash', 'acct:<id>', 'society:<name>') for what the
--- player wants to do with it: 'view', 'withdraw' (money leaves it) or 'deposit' (money enters it).
function App.Resolve(Player, cid, ref, need)
    if type(ref) ~= 'string' or #ref > 64 then return nil, 'bad_account' end
    if ref == 'personal' then
        return { kind = 'personal', ledger = ('player:%s:bank'):format(cid), label = 'Personal account' }
    end
    if ref == 'cash' then
        if need ~= 'view' then return nil, 'cash_at_counter' end
        return { kind = 'cash', ledger = ('player:%s:cash'):format(cid), label = 'Cash' }
    end
    local id = ref:match('^acct:(%d+)$')
    if id and #id <= 12 then
        local account, perms = BankingAccountsInternal.getAccountAccess(tonumber(id), cid)
        if not account or not perms then return nil, 'not_authorized' end
        if need == 'withdraw' and not perm(perms, 'can_withdraw') then return nil, 'not_authorized' end
        if need == 'deposit' and not perm(perms, 'can_deposit') then return nil, 'not_authorized' end
        return { kind = 'acct', id = account.id, ledger = 'acct:' .. account.id, label = account.label, iban = account.iban }
    end
    local name = ref:match('^society:([%w_%-%.]+)$')
    if name and #name <= 50 then
        local acc = BankingInternal.Accounts[name]
        if not acc or not BankingInternal.canUseAccount(Player, acc) then return nil, 'not_authorized' end
        return { kind = 'society', name = name, ledger = 'society:' .. name, label = societyLabel(name, acc.account_type) }
    end
    return nil, 'bad_account'
end

--- What this citizen sent to other people from the app in the last 24 hours.
function App.DailyUsed(cid)
    local used = MySQL.scalar.await([[SELECT COALESCE(SUM(amount), 0) FROM pf_transactions
        WHERE idempotency_key LIKE ? AND state = 'completed' AND created_at >= (NOW() - INTERVAL 1 DAY)]], { ('bankapp:%s:x:%%'):format(cid) })
    return tonumber(used) or 0
end

local function maskCard(c)
    local number = tostring(c.number or c.card_number or '')
    return number:gsub('%s', ''):sub(-4)
end

-- ── handlers ────────────────────────────────────────────────────────

local viewers = {}   -- [src] = os.time() the player last opened the app (balance pushes go to them)

function App.Overview(src)
    local Player, cid = getPlayer(src)
    if not Player then return { ok = false, error = 'no_player' } end
    viewers[src] = os.time()
    local snap = run('getAccountsData', src) or {}
    local accounts = {}
    for _, a in ipairs(snap.accounts or {}) do
        local p = a.myPerms or {}
        local entry = {
            ref = 'acct:' .. a.id, id = a.id, label = a.label, iban = a.iban, type = a.type,
            balance = tonumber(a.balance) or 0, color = a.color, isOwner = a.isOwner == true,
            perms = { withdraw = perm(p, 'can_withdraw'), deposit = perm(p, 'can_deposit'), cards = perm(p, 'can_cards'), manage = perm(p, 'can_manage') },
        }
        if entry.perms.manage and type(a.members) == 'table' then
            entry.members = {}
            for _, m in ipairs(a.members) do
                entry.members[#entry.members + 1] = {
                    citizenid = m.citizenid, name = m.name, owner = m.citizenid == a.owner,
                    withdraw = tonumber(m.can_withdraw) == 1, deposit = tonumber(m.can_deposit) == 1,
                    cards = tonumber(m.can_cards) == 1, manage = tonumber(m.can_manage) == 1,
                }
            end
        end
        accounts[#accounts + 1] = entry
    end
    local finance = run('getFinance', src) or {}
    local debt = 0
    for _, l in ipairs(finance.loans or {}) do debt = debt + (tonumber(l.balance) or 0) end
    for _, c in ipairs(finance.cards or {}) do debt = debt + (tonumber(c.balance) or 0) end
    local money = Player.PlayerData.money or {}
    local ci = Player.PlayerData.charinfo or {}
    return {
        ok = true,
        me = { name = ((ci.firstname or '') .. ' ' .. (ci.lastname or '')):gsub('^%s+', ''), citizenid = cid },
        personal = { balance = tonumber(money.bank) or 0, cash = tonumber(money.cash) or 0, iban = snap.personal and snap.personal.iban or nil },
        accounts = accounts,
        societies = App.Societies(Player),
        finance = { score = finance.score, scoreMin = finance.scoreMin, scoreMax = finance.scoreMax, debt = debt,
            loans = #(finance.loans or {}), cards = #(finance.cards or {}) },
        limits = { maxTransfer = cfg('maxTransfer', 250000), maxInternal = cfg('maxInternal', 10000000),
            dailyLimit = cfg('dailyTransferLimit', 1000000), dailyUsed = App.DailyUsed(cid) },
        branches = BankBranches and BankBranches.List() or {},
    }
end

local DAYS = { [1] = true, [7] = true, [30] = true, [90] = true, [365] = true }

--- Completed ledger lines of one ledger account, newest first.
--- filter = { direction = 'in'|'out', kind, search, days, before = <row id>, limit }
function App.QueryStatement(ledgerRef, cid, filter)
    filter = type(filter) == 'table' and filter or {}
    local where, params = {}, {}
    local dir = filter.direction
    if dir == 'in' then where[#where + 1] = 'to_account = ?'; params[#params + 1] = ledgerRef
    elseif dir == 'out' then where[#where + 1] = 'from_account = ?'; params[#params + 1] = ledgerRef
    else
        where[#where + 1] = '(from_account = ? OR to_account = ?)'
        params[#params + 1] = ledgerRef; params[#params + 1] = ledgerRef
    end
    where[#where + 1] = "state = 'completed'"
    if type(filter.kind) == 'string' and #filter.kind <= 32 and filter.kind:match('^[%w_%-%.]+$') then
        where[#where + 1] = 'kind = ?'; params[#params + 1] = filter.kind
    end
    local search = type(filter.search) == 'string' and (filter.search:gsub('[%c]', '')):sub(1, 40) or ''
    if search ~= '' then
        where[#where + 1] = 'reason LIKE ?'
        params[#params + 1] = '%' .. search:gsub('[\\%%_]', '\\%0') .. '%'
    end
    local days = tonumber(filter.days)
    if days and DAYS[days] then where[#where + 1] = 'created_at >= (NOW() - INTERVAL ? DAY)'; params[#params + 1] = days end

    local summary
    local before = positiveInt(filter.before)
    if not before then
        -- money in and out over the whole filtered period (first page only)
        local sp = { ledgerRef, ledgerRef }
        for _, v in ipairs(params) do sp[#sp + 1] = v end
        local row = MySQL.single.await(([[SELECT COALESCE(SUM(CASE WHEN to_account = ? THEN amount ELSE 0 END), 0) AS credits,
            COALESCE(SUM(CASE WHEN from_account = ? THEN amount ELSE 0 END), 0) AS debits, COUNT(*) AS line_count
            FROM pf_transactions WHERE %s]]):format(table.concat(where, ' AND ')), sp)
        if row then summary = { moneyIn = tonumber(row.credits) or 0, moneyOut = tonumber(row.debits) or 0, lines = tonumber(row.line_count) or 0 } end
    else
        where[#where + 1] = 'id < ?'; params[#params + 1] = before
    end

    local limit = math.max(1, math.min(100, math.floor(tonumber(filter.limit) or cfg('statementPageSize', 25))))
    local rows = MySQL.query.await(([[SELECT id, tx_id, kind, from_account, to_account, amount, reason, metadata, UNIX_TIMESTAMP(created_at) AS at
        FROM pf_transactions WHERE %s ORDER BY id DESC LIMIT %d]]):format(table.concat(where, ' AND '), limit + 1), params) or {}

    local hasMore = #rows > limit
    if hasMore then rows[#rows] = nil end
    local refs = {}
    for _, r in ipairs(rows) do refs[r.from_account == ledgerRef and r.to_account or r.from_account] = true end
    local who = describeAll(refs, cid)
    local out = {}
    for _, r in ipairs(rows) do
        local outgoing = r.from_account == ledgerRef
        local note
        if type(r.metadata) == 'string' and r.metadata ~= '' then
            local ok, meta = pcall(json.decode, r.metadata)
            if ok and type(meta) == 'table' and type(meta.note) == 'string' then note = meta.note:sub(1, 100) end
        end
        out[#out + 1] = {
            id = tonumber(r.id), txId = r.tx_id, at = tonumber(r.at), amount = tonumber(r.amount) or 0,
            direction = outgoing and 'out' or 'in', kind = r.kind, reason = r.reason, note = note,
            counterparty = who[outgoing and r.to_account or r.from_account],
        }
    end
    return { rows = out, hasMore = hasMore, nextBefore = hasMore and out[#out] and out[#out].id or nil, summary = summary }
end

function App.Statement(src, p)
    local Player, cid = getPlayer(src)
    if not Player then return { ok = false, error = 'no_player' } end
    local acc, err = App.Resolve(Player, cid, p.account or 'personal', 'view')
    if not acc then return { ok = false, error = err } end
    local res = App.QueryStatement(acc.ledger, cid, {
        direction = (p.direction == 'in' or p.direction == 'out') and p.direction or nil,
        kind = p.kind, search = p.search, days = p.days, before = p.before,
    })
    res.ok = true
    res.account = { ref = p.account or 'personal', label = acc.label, iban = acc.iban }
    return res
end

local SOCIETY_ERRORS = {
    insufficient_funds = 'Insufficient balance', not_authorized = 'No permission', bad_amount = 'Invalid amount',
    already_processed = 'This transaction was already processed', unknown_account = 'Account not found',
}

local function society(src, name, direction, amount, key)
    local res = BankingInternal.SocietyTransfer(src, { society = name, direction = direction, account = 'bank', amount = amount, key = key })
    if res.ok then
        return { ok = true, txId = res.txId, duplicate = res.duplicate,
            message = (direction == 'deposit' and 'Deposited $%s' or 'Withdrew $%s'):format(res.amount) }
    end
    return { ok = false, error = res.error, message = SOCIETY_ERRORS[res.error] or L.Message(res.error) }
end

--- Moves money. payload = { ref, from, amount, note, to = { type = 'own', account } | { type = 'iban', iban }
--- | { type = 'citizen', citizenid } }. Own moves: personal <-> shared account (by permission), shared ->
--- shared (by IBAN), personal <-> society (bosses). Payments to others come from the personal or a shared
--- account and count toward the daily limit.
function App.Transfer(src, p)
    local Player, cid = getPlayer(src)
    if not Player then return { ok = false, error = 'no_player' } end
    local ref = requestRef(p)
    if not ref or type(p.to) ~= 'table' then return { ok = false, error = 'bad_request' } end
    local amount = positiveInt(p.amount)
    if not amount then return { ok = false, error = 'bad_amount' } end
    local note = type(p.note) == 'string' and p.note or nil
    local from, err = App.Resolve(Player, cid, p.from, 'withdraw')
    if not from then return { ok = false, error = err } end

    local toType = p.to.type
    if toType == 'own' then
        local to, err2 = App.Resolve(Player, cid, p.to.account, 'deposit')
        if not to then return { ok = false, error = err2 } end
        if to.ledger == from.ledger then return { ok = false, error = 'same_account' } end
        if amount > cfg('maxInternal', 10000000) then return { ok = false, error = 'over_limit' } end
        local key = ('bankapp:%s:i:%s'):format(cid, ref)
        if not L.GetTransaction(key) and onCooldown(cid) then return { ok = false, error = 'slow_down' } end
        if from.kind == 'personal' and to.kind == 'acct' then
            return fromCallback(BankingAccountOps.deposit(src, { accountId = to.id, amount = amount }, key))
        elseif from.kind == 'acct' and to.kind == 'personal' then
            return fromCallback(BankingAccountOps.withdraw(src, { accountId = from.id, amount = amount }, key))
        elseif from.kind == 'acct' and to.kind == 'acct' then
            return fromCallback(BankingAccountOps.transfer(src, { fromRef = from.id, toIban = to.iban, amount = amount, note = note }, key))
        elseif from.kind == 'personal' and to.kind == 'society' then
            return society(src, to.name, 'deposit', amount, key)
        elseif from.kind == 'society' and to.kind == 'personal' then
            return society(src, from.name, 'withdraw', amount, key)
        end
        return { ok = false, error = 'unsupported_route' }
    elseif toType == 'iban' or toType == 'citizen' then
        if from.kind ~= 'personal' and from.kind ~= 'acct' then return { ok = false, error = 'unsupported_route' } end
        if amount > cfg('maxTransfer', 250000) then return { ok = false, error = 'over_limit' } end
        local iban
        if toType == 'iban' then
            iban = type(p.to.iban) == 'string' and p.to.iban:upper():gsub('%s', '') or ''
            if #iban > 24 or not iban:match('^PF%d+$') then return { ok = false, error = 'bad_iban' } end
        else
            local target = type(p.to.citizenid) == 'string' and p.to.citizenid:upper():gsub('%s', '') or ''
            if target == '' or #target > 20 or not target:match('^%w+$') then return { ok = false, error = 'bad_citizen' } end
            if target == cid and from.kind == 'personal' then return { ok = false, error = 'same_account' } end
            local exists = QBCore.Functions.GetPlayerByCitizenId(target)
                or MySQL.scalar.await('SELECT 1 FROM players WHERE citizenid = ? LIMIT 1', { target })
            if not exists then return { ok = false, error = 'unknown_citizen' } end
            iban = BankingAccountsInternal.getPersonalIban(target)
            if not iban then return { ok = false, error = 'server_error' } end
        end
        local key = ('bankapp:%s:x:%s'):format(cid, ref)
        -- a retry of an action already recorded skips the limits: the ledger returns the first result
        if not L.GetTransaction(key) then
            if App.DailyUsed(cid) + amount > cfg('dailyTransferLimit', 1000000) then return { ok = false, error = 'daily_limit' } end
            if onCooldown(cid) then return { ok = false, error = 'slow_down' } end
        end
        local res = BankingAccountOps.transfer(src, { fromRef = from.kind == 'personal' and 'personal' or from.id, toIban = iban, amount = amount, note = note }, key)
        return fromCallback(res)
    end
    return { ok = false, error = 'bad_request' }
end

-- ── loans, credit and cards (the bank screen's own handlers) ────────

local function productLabel(id)
    for _, p in ipairs(Config.creditCards.products or {}) do if p.id == id then return p.label end end
    return id
end

function App.Finance(src)
    local Player, cid = getPlayer(src)
    if not Player then return { ok = false, error = 'no_player' } end
    local f = run('getFinance', src)
    if type(f) ~= 'table' then return { ok = false, error = 'server_error' } end
    local now = os.time()
    local loans, cards, products, held = {}, {}, {}, {}
    for _, l in ipairs(f.loans or {}) do
        loans[#loans + 1] = {
            id = tonumber(l.id), tier = l.tier, principal = tonumber(l.principal), balance = tonumber(l.balance), apr = tonumber(l.apr),
            payment = tonumber(l.payment_amount), paymentsTotal = tonumber(l.payments_total), paymentsMade = tonumber(l.payments_made),
            missed = tonumber(l.missed_payments), nextPaymentIn = math.max(0, (tonumber(l.next_payment) or now) - now),
        }
    end
    for _, c in ipairs(f.cards or {}) do
        held[c.card_id] = true
        cards[#cards + 1] = { id = tonumber(c.id), product = c.card_id, label = productLabel(c.card_id), last4 = maskCard(c),
            limit = tonumber(c.credit_limit), balance = tonumber(c.balance), apr = tonumber(c.apr) }
    end
    for _, p in ipairs(f.cardProducts or {}) do
        products[#products + 1] = { id = p.id, label = p.label, minScore = p.minScore, limit = p.limit, apr = p.apr,
            eligible = (tonumber(f.score) or 0) >= p.minScore, held = held[p.id] == true }
    end
    local tiers = {}
    for i, t in ipairs(f.tiers or {}) do
        tiers[#tiers + 1] = { index = i, name = t.name, minScore = t.minScore, amountMin = t.amountMin, amountMax = t.amountMax,
            apr = t.apr, payments = t.payments, eligible = (tonumber(f.score) or 0) >= t.minScore }
    end
    local debit = {}
    for _, c in ipairs(MySQL.query.await([[SELECT c.id, c.account_id, c.number, c.exp, c.design, c.locked, a.label AS account_label
        FROM bank_account_cards c LEFT JOIN bank_accounts_v2 a ON a.id = c.account_id
        WHERE c.citizenid = ? AND c.cancelled = 0 ORDER BY c.id ASC]], { cid }) or {}) do
        debit[#debit + 1] = { id = tonumber(c.id), last4 = maskCard(c), exp = c.exp, design = c.design, locked = tonumber(c.locked) == 1,
            account = c.account_id and ('acct:' .. c.account_id) or 'personal', accountLabel = c.account_label or 'Personal account' }
    end
    return {
        ok = true, score = f.score, scoreMin = f.scoreMin, scoreMax = f.scoreMax, loans = loans, cards = cards,
        tiers = tiers, products = products, maxActiveLoans = f.maxActiveLoans, advanceFeePct = f.advanceFeePct,
        debitCards = debit, maxDebitCards = Config.MaxCardsPerAccount or 4,
    }
end

local CARD_DESIGNS = { classic = true, midnight = true, gold = true, ruby = true, ocean = true }

-- money actions on loans and cards: one at a time per player, ids and amounts checked here and again
-- by the handler itself
local function moneyAction(src, fn)
    local _, cid = getPlayer(src)
    if not cid then return { ok = false, error = 'no_player' } end
    if onCooldown(cid) then return { ok = false, error = 'slow_down' } end
    return fn()
end

local handlers = {
    overview = function(src) return App.Overview(src) end,
    statement = function(src, p) return App.Statement(src, p) end,
    transfer = function(src, p) return App.Transfer(src, p) end,
    finance = function(src) return App.Finance(src) end,
    branches = function() return { ok = true, branches = BankBranches and BankBranches.List() or {} } end,

    payLoan = function(src, p)
        local id = positiveInt(p.loanId)
        if not id then return { ok = false, error = 'bad_request' } end
        return moneyAction(src, function() return fromCallback(run('payLoan', src, { loanId = id })) end)
    end,
    payoffLoan = function(src, p)
        local id = positiveInt(p.loanId)
        if not id then return { ok = false, error = 'bad_request' } end
        return moneyAction(src, function() return fromCallback(run('payoffLoan', src, { loanId = id })) end)
    end,
    applyLoan = function(src, p)
        local tier, amount = positiveInt(p.tierIndex, 50), positiveInt(p.amount)
        if not tier or not amount then return { ok = false, error = 'bad_request' } end
        return moneyAction(src, function() return fromCallback(run('applyLoan', src, { tierIndex = tier, amount = amount })) end)
    end,
    payCard = function(src, p)
        local id, amount = positiveInt(p.cardId), positiveInt(p.amount)
        if not id or not amount then return { ok = false, error = 'bad_request' } end
        return moneyAction(src, function() return fromCallback(run('payCard', src, { cardId = id, amount = amount })) end)
    end,
    cardAdvance = function(src, p)
        local id, amount = positiveInt(p.cardId), positiveInt(p.amount)
        if not id or not amount then return { ok = false, error = 'bad_request' } end
        return moneyAction(src, function() return fromCallback(run('cardAdvance', src, { cardId = id, amount = amount })) end)
    end,
    orderCreditCard = function(src, p)
        if type(p.product) ~= 'string' or #p.product > 32 or not p.product:match('^[%w_]+$') then return { ok = false, error = 'bad_request' } end
        return fromCallback(run('orderCreditCard', src, { cardId = p.product }))
    end,
    createCard = function(src, p)
        local target = p.account == 'personal' and 'personal' or nil
        if not target then
            local id = type(p.account) == 'string' and p.account:match('^acct:(%d+)$')
            target = id and positiveInt(id) or nil
        end
        if not target then return { ok = false, error = 'bad_request' } end
        local design = CARD_DESIGNS[p.design] and p.design or 'classic'
        return fromCallback(run('createCard', src, { accountRef = target, design = design }))
    end,
    toggleCardLock = function(src, p)
        local id = positiveInt(p.cardId)
        if not id then return { ok = false, error = 'bad_request' } end
        return fromCallback(run('toggleCardLock', src, { cardId = id }))
    end,
    cancelCard = function(src, p)
        local id = positiveInt(p.cardId)
        if not id then return { ok = false, error = 'bad_request' } end
        return fromCallback(run('cancelCard', src, { cardId = id }))
    end,

    -- shared account members (the callbacks require can_manage)
    addMember = function(src, p)
        local id = type(p.account) == 'string' and positiveInt(p.account:match('^acct:(%d+)$'))
        if not id or type(p.citizenid) ~= 'string' then return { ok = false, error = 'bad_request' } end
        return fromCallback(run('addMember', src, { accountId = id, citizenid = p.citizenid:upper(), perms = type(p.perms) == 'table' and p.perms or { can_deposit = true } }))
    end,
    updateMember = function(src, p)
        local id = type(p.account) == 'string' and positiveInt(p.account:match('^acct:(%d+)$'))
        if not id or type(p.citizenid) ~= 'string' or type(p.perms) ~= 'table' then return { ok = false, error = 'bad_request' } end
        return fromCallback(run('updateMember', src, { accountId = id, citizenid = p.citizenid, perms = p.perms }))
    end,
    removeMember = function(src, p)
        local id = type(p.account) == 'string' and positiveInt(p.account:match('^acct:(%d+)$'))
        if not id or type(p.citizenid) ~= 'string' then return { ok = false, error = 'bad_request' } end
        return fromCallback(run('removeMember', src, { accountId = id, citizenid = p.citizenid }))
    end,
    renameAccount = function(src, p)
        local id = type(p.account) == 'string' and positiveInt(p.account:match('^acct:(%d+)$'))
        if not id or type(p.label) ~= 'string' then return { ok = false, error = 'bad_request' } end
        return fromCallback(run('accountRename', src, { accountId = id, label = p.label }))
    end,
}
App.Handlers = handlers

function App.Register()
    if GetResourceState('pf-devices') ~= 'started' then return false end
    local devices = exports['pf-devices']
    devices:RegisterApp({
        id = APP_ID, name = 'Bank', icon = '🏦', entry = 'html/apps/bank.js', styles = { 'html/apps/bank.css' },
        devices = { 'tablet', 'computer' }, category = 'apps', order = 6, access = { anyone = true },
        window = { width = 980, height = 660 },
        description = 'Accounts, statements, transfers, loans and cards',
    })
    devices:RegisterAppHandlers(APP_ID, handlers)
    return true
end

AddEventHandler('onResourceStart', function(resource)
    if resource == GetCurrentResourceName() or resource == 'pf-devices' then App.Register() end
end)
AddEventHandler('pf-devices:server:ready', function() App.Register() end)

-- Live balances for players who opened the app in the last 15 minutes (coalesced per player).
local pendingPush = {}
AddEventHandler('QBCore:Server:OnMoneyChange', function(src, moneytype)
    src = tonumber(src)
    if not src or (moneytype ~= 'bank' and moneytype ~= 'cash') then return end
    local seen = viewers[src]
    if not seen or os.time() - seen > 900 or pendingPush[src] then return end
    pendingPush[src] = true
    SetTimeout(1500, function()
        pendingPush[src] = nil
        local Player = getPlayer(src)
        if not Player or GetResourceState('pf-devices') ~= 'started' then return end
        local m = Player.PlayerData.money or {}
        exports['pf-devices']:Push(src, APP_ID, 'balance', { bank = tonumber(m.bank) or 0, cash = tonumber(m.cash) or 0 })
    end)
end)

AddEventHandler('playerDropped', function()
    local src = tonumber(source)
    if src then viewers[src], pendingPush[src] = nil, nil end
end)

exports('GetAccountStatement', function(src, ref, filter)
    local Player, cid = getPlayer(src)
    if not Player then return { ok = false, error = 'no_player' } end
    local acc, err = App.Resolve(Player, cid, ref, 'view')
    if not acc then return { ok = false, error = err } end
    local res = App.QueryStatement(acc.ledger, cid, filter)
    res.ok = true
    return res
end)

function App.__reset() lastAction, viewers, pendingPush = {}, {}, {} end
